/**
 * Demo seed — wipes the Workspace databases and fills them with believable,
 * fully fake data generated by @faker-js/faker.
 *
 *   npm run seed            (from workspace/backend, or `npm run seed` at repo root)
 *
 * Deterministic: faker is seeded, so every reset produces the same dataset
 * (dates are relative to "today" so the demo always looks current).
 */
process.env.TZ = process.env.TZ || 'Asia/Kolkata';
import 'dotenv/config';

import mongoose, { Types } from 'mongoose';
import { fakerEN_IN as faker } from '@faker-js/faker';

import { privateConn } from '../config/connections';
import User, { IUser } from '../models/User';
import Department from '../models/Department';
import Project from '../models/Project';
import Task from '../models/Task';
import SOP from '../models/SOP';
import Attendance from '../models/Attendance';
import Comment from '../models/Comment';
import Note from '../models/Note';
import Resource from '../models/Resource';
import CalendarEvent from '../models/CalendarEvent';
import Notification from '../models/Notification';
import Credential from '../models/Credential';
import Conversation from '../models/Conversation';
import Message from '../models/Message';
import { encryptSecret } from '../utils/crypto';

const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017/demo_pm';
export const DEMO_PASSWORD = 'demo1234';

faker.seed(20260101);

// ── helpers ────────────────────────────────────────────────────────────────
const pick = <T>(arr: readonly T[]): T => faker.helpers.arrayElement(arr as T[]);
const some = <T>(arr: readonly T[], min: number, max: number): T[] =>
  faker.helpers.arrayElements(arr as T[], { min, max });
const today = (() => { const d = new Date(); d.setHours(0, 0, 0, 0); return d; })();
const daysFromToday = (n: number) => { const d = new Date(today); d.setDate(d.getDate() + n); return d; };
const at = (day: Date, h: number, m: number) => { const d = new Date(day); d.setHours(h, m, 0, 0); return d; };
const isWeekend = (d: Date) => d.getDay() === 0 || d.getDay() === 6;
const hhmm = (h: number, m: number) => `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;

const DEPARTMENTS = [
  { name: 'Design',      color: '#ec4899', canSocialMedia: false, templates: ['Landing page mockup', 'Brand style guide', 'Social creatives pack'] },
  { name: 'Development', color: '#6366f1', canSocialMedia: false, templates: ['Website build', 'Bug fix sprint', 'Performance audit'] },
  { name: 'Marketing',   color: '#f59e0b', canSocialMedia: true,  templates: ['Paid ads campaign', 'Monthly performance report', 'Email newsletter'] },
  { name: 'SEO',         color: '#10b981', canSocialMedia: false, templates: ['Keyword research', 'Technical SEO audit', 'On-page optimisation'] },
  { name: 'Content',     color: '#0ea5e9', canSocialMedia: true,  templates: ['Blog article', 'Video script', 'Website copy'] },
  { name: 'Operations',  color: '#64748b', canSocialMedia: false, templates: ['Client onboarding', 'Monthly invoicing', 'Vendor review'] },
] as const;

const ENGAGEMENTS = [
  { kind: 'Website Revamp',          tags: ['web', 'design'],      depts: ['Design', 'Development', 'Content'] },
  { kind: 'SEO Retainer',            tags: ['seo', 'retainer'],    depts: ['SEO', 'Content'] },
  { kind: 'Performance Marketing',   tags: ['ads', 'marketing'],   depts: ['Marketing', 'Design'] },
  { kind: 'Social Media Management', tags: ['social', 'content'],  depts: ['Content', 'Design', 'Marketing'] },
  { kind: 'E-commerce Store',        tags: ['ecommerce', 'web'],   depts: ['Development', 'Design', 'SEO'] },
  { kind: 'Brand Identity',          tags: ['branding', 'design'], depts: ['Design', 'Content'] },
  { kind: 'Mobile App MVP',          tags: ['mobile', 'product'],  depts: ['Development', 'Design'] },
  { kind: 'Content Marketing',       tags: ['content', 'seo'],     depts: ['Content', 'SEO', 'Marketing'] },
] as const;

const TASK_VERBS = ['Draft', 'Design', 'Review', 'Implement', 'Optimise', 'Audit', 'Publish', 'Set up', 'Refine', 'Test', 'Plan', 'Write'];
const TASK_OBJECTS = [
  'homepage hero section', 'pricing page', 'blog post on industry trends', 'Google Ads campaign', 'Meta ads creatives',
  'XML sitemap', 'product listing page', 'checkout flow', 'monthly analytics report', 'email welcome sequence',
  'brand colour palette', 'logo variations', 'Instagram content calendar', 'landing page copy', 'contact form',
  'site speed issues', 'schema markup', 'competitor analysis', 'keyword cluster map', 'onboarding checklist',
  'API integration', 'mobile navigation', 'case study page', 'YouTube video script', 'newsletter template',
];
const CHECKLIST = ['Gather requirements', 'Share first draft', 'Incorporate feedback', 'Client sign-off', 'QA pass', 'Hand over'];
const STATUS_WEIGHTS = [
  { value: 'done', weight: 35 }, { value: 'in_progress', weight: 20 }, { value: 'in_review', weight: 10 },
  { value: 'todo', weight: 20 }, { value: 'backlog', weight: 15 },
];
type TaskStatus = 'backlog' | 'todo' | 'in_progress' | 'in_review' | 'done';

async function clearAll() {
  await Promise.all([
    User.deleteMany({}), Department.deleteMany({}), Project.deleteMany({}), Task.deleteMany({}),
    SOP.deleteMany({}), Attendance.deleteMany({}), Comment.deleteMany({}), Note.deleteMany({}),
    Resource.deleteMany({}), CalendarEvent.deleteMany({}), Notification.deleteMany({}),
    Credential.deleteMany({}), Conversation.deleteMany({}), Message.deleteMany({}),
  ]);
  // Collections not seeded but which may hold visitor-created data
  const extra = ['pushsubscriptions', 'socialaccounts', 'socialposts', 'mediafiles', 'rooms', 'tables',
                 'tableinstances', 'projecttabs', 'savedmessages', 'userchatsettings'];
  for (const db of [mongoose.connection.db, privateConn.db]) {
    if (!db) continue;
    const existing = new Set((await db.listCollections().toArray()).map((c) => c.name));
    for (const name of extra) if (existing.has(name)) await db.collection(name).deleteMany({});
  }
}

export async function seedWorkspace() {
  await mongoose.connect(MONGO_URI);
  await privateConn.asPromise();
  console.log('Connected — clearing existing data…');
  await clearAll();

  // ── Users ────────────────────────────────────────────────────────────────
  const demoAccounts = [
    { name: 'Alex Morgan',  email: 'admin@demo.com',   role: 'admin'   },
    { name: 'Priya Desai',  email: 'manager@demo.com', role: 'manager' },
    { name: 'Rohan Mehta',  email: 'member@demo.com',  role: 'member'  },
    { name: 'Sam Taylor',   email: 'viewer@demo.com',  role: 'viewer'  },
  ] as const;

  const teamDefs = Array.from({ length: 12 }, (_, i) => {
    const first = faker.person.firstName();
    const last = faker.person.lastName();
    return {
      name: `${first} ${last}`,
      email: `${first}.${last}`.toLowerCase().replace(/[^a-z0-9.]/g, '') + `${i}@demo.com`,
      role: i < 2 ? 'manager' : 'member',
    } as const;
  });

  const users: IUser[] = [];
  for (const u of [...demoAccounts, ...teamDefs]) {
    users.push(await User.create({
      ...u,
      password: DEMO_PASSWORD,
      isActive: true,
      lateThreshold: '09:30',
      lastSeen: faker.date.recent({ days: 2 }),
    }));
  }
  const [admin, manager, member] = users;
  const staff = users.filter((u) => u.role !== 'viewer');
  const oid = (u: IUser) => u._id as Types.ObjectId;
  console.log(`  users:          ${users.length}`);

  // ── Departments ──────────────────────────────────────────────────────────
  const team = staff.slice(1); // everyone except admin gets a home department
  const departments = [];
  for (const [i, d] of DEPARTMENTS.entries()) {
    const deptMembers = team.filter((_, idx) => idx % DEPARTMENTS.length === i);
    if (d.name === 'Development' && !deptMembers.includes(member)) deptMembers.push(member);
    const head = i <= 1 ? manager : deptMembers[0] ?? manager;
    departments.push(await Department.create({
      name: d.name,
      description: `${d.name} team — ${faker.company.catchPhrase().toLowerCase()}.`,
      color: d.color,
      heads: [head._id],
      members: deptMembers.map(oid),
      collaborators: [admin._id],
      canSocialMedia: d.canSocialMedia,
      taskTemplates: d.templates.map((t) => ({
        title: t,
        description: faker.lorem.sentence(),
        priority: pick(['low', 'medium', 'high'] as const),
        estimatedHours: faker.number.int({ min: 2, max: 16 }),
        checklist: some(CHECKLIST, 2, 4),
        types: [
          { title: `${t} — Standard`, priority: 'medium', estimatedHours: faker.number.int({ min: 2, max: 8 }), checklist: some(CHECKLIST, 2, 3) },
          { title: `${t} — Premium`,  priority: 'high',   estimatedHours: faker.number.int({ min: 6, max: 20 }), checklist: some(CHECKLIST, 3, 5) },
        ],
      })),
    }));
  }
  const deptByName = new Map(departments.map((d) => [d.name, d]));
  console.log(`  departments:    ${departments.length}`);

  // ── SOPs ─────────────────────────────────────────────────────────────────
  const sopDefs = [
    { title: 'New Website Launch', steps: [['Discovery call & brief', 'Operations'], ['Wireframes', 'Design'], ['Visual design', 'Design'], ['Frontend build', 'Development'], ['Copywriting', 'Content'], ['On-page SEO', 'SEO'], ['Launch & handover', 'Development']] },
    { title: 'Monthly Social Retainer', steps: [['Content calendar', 'Content'], ['Creative production', 'Design'], ['Scheduling & publishing', 'Marketing'], ['Performance report', 'Marketing']] },
    { title: 'SEO Onboarding', steps: [['Technical audit', 'SEO'], ['Keyword research', 'SEO'], ['Content gap plan', 'Content'], ['Fix critical issues', 'Development']] },
  ] as const;
  const sops = [];
  for (const s of sopDefs) {
    sops.push(await SOP.create({
      title: s.title,
      description: `Standard operating procedure for ${s.title.toLowerCase()} projects.`,
      status: 'published',
      createdBy: admin._id,
      steps: s.steps.map(([title, dept], i) => ({
        order: i + 1,
        title,
        description: faker.lorem.sentence(),
        department: deptByName.get(dept)!._id,
        estimatedHours: faker.number.int({ min: 2, max: 12 }),
        dependsOn: i === 0 ? [] : [i],
        positionX: 80 + i * 260,
        positionY: 120 + (i % 2) * 80,
      })),
    }));
  }
  console.log(`  sops:           ${sops.length}`);

  // ── Projects (each project is also a "client" in the Finance app) ────────
  const statuses = ['active', 'active', 'active', 'active', 'planning', 'on_hold', 'completed', 'active'] as const;
  const projects = [];
  for (const [i, eng] of ENGAGEMENTS.entries()) {
    const company = faker.company.name().replace(/,/g, '');
    const start = daysFromToday(-faker.number.int({ min: 20, max: 160 }));
    const end = statuses[i] === 'completed'
      ? daysFromToday(-faker.number.int({ min: 3, max: 15 }))
      : daysFromToday(faker.number.int({ min: 10, max: 120 }));
    const pool = eng.depts.flatMap((d) => (deptByName.get(d)!.members as Types.ObjectId[]).map(String));
    const memberIds = [...new Set([...some(pool, 2, 4), String(member._id)])].filter((id) => id !== String(manager._id));
    projects.push(await Project.create({
      title: `${company} — ${eng.kind}`,
      description: `${eng.kind} engagement for ${company}. ${faker.company.buzzPhrase()}.`,
      status: statuses[i],
      priority: pick(['low', 'medium', 'high', 'critical'] as const),
      startDate: start,
      endDate: end,
      owner: i % 2 === 0 ? admin._id : manager._id,
      members: [
        { user: manager._id, role: 'lead' },
        ...memberIds.map((id) => ({ user: new Types.ObjectId(id), role: 'member' as const })),
        { user: users[3]._id, role: 'viewer' },
      ],
      tags: [...eng.tags],
      links: [{ title: 'Staging site', url: `https://staging.example.com/${i + 1}` }],
    }));
  }
  console.log(`  projects:       ${projects.length}`);

  // ── Tasks ────────────────────────────────────────────────────────────────
  const tasks = [];
  for (const [pi, project] of projects.entries()) {
    const eng = ENGAGEMENTS[pi];
    const projectMembers = project.members.filter((m) => m.role !== 'viewer').map((m) => m.user as Types.ObjectId);
    const n = faker.number.int({ min: 8, max: 14 });
    let prev: Types.ObjectId | undefined;
    for (let t = 0; t < n; t++) {
      const status: TaskStatus = project.status === 'completed' ? 'done'
        : project.status === 'planning' ? pick(['backlog', 'todo'] as const)
        : faker.helpers.weightedArrayElement(STATUS_WEIGHTS) as TaskStatus;
      const est = faker.number.int({ min: 1, max: 16 });
      const elapsed = status === 'done' ? est * 3600 * faker.number.float({ min: 0.7, max: 1.3 })
        : status === 'in_progress' || status === 'in_review' ? est * 3600 * faker.number.float({ min: 0.2, max: 0.8 }) : 0;
      const started = status !== 'backlog' && status !== 'todo';
      const checklist = some(CHECKLIST, 2, 5).map((title, ci, arr) => ({
        title, completed: status === 'done' || (started && ci < arr.length / 2),
      }));
      const task = await Task.create({
        title: `${pick(TASK_VERBS)} ${pick(TASK_OBJECTS)}`,
        description: faker.lorem.paragraph(),
        project: project._id,
        department: deptByName.get(pick(eng.depts))!._id,
        status,
        priority: faker.helpers.weightedArrayElement([
          { value: 'low' as const, weight: 2 }, { value: 'medium' as const, weight: 5 },
          { value: 'high' as const, weight: 3 }, { value: 'critical' as const, weight: 1 },
        ]),
        assignees: some(projectMembers, 1, 2),
        reporter: project.owner,
        // a few overdue items keep the dashboards interesting
        dueDate: daysFromToday(status === 'done' ? -faker.number.int({ min: 1, max: 40 }) : faker.number.int({ min: -4, max: 30 })),
        estimatedHours: est,
        totalElapsedSeconds: Math.round(elapsed),
        timerStatus: status === 'done' ? 'finished' : elapsed > 0 ? 'paused' : 'idle',
        tags: some(eng.tags, 1, 2),
        order: t,
        checklist,
        dependencies: prev && t % 4 === 3 ? [prev] : [],
      });
      prev = task._id as Types.ObjectId;
      tasks.push(task);
    }
  }
  // Personal to-dos for the demo accounts
  for (const u of [admin, manager, member]) {
    for (let i = 0; i < 3; i++) {
      tasks.push(await Task.create({
        title: pick(['Prepare weekly update', 'Review team timesheets', 'Plan next sprint', 'Clear inbox backlog', 'Update portfolio deck', '1:1 meeting notes']),
        isPersonal: true, status: pick(['todo', 'in_progress', 'done'] as const), priority: 'medium',
        assignees: [u._id], reporter: u._id, dueDate: daysFromToday(faker.number.int({ min: 0, max: 7 })),
      }));
    }
  }
  for (const project of projects) {
    const pt = tasks.filter((t) => String(t.project) === String(project._id));
    const done = pt.filter((t) => t.status === 'done').length;
    await Project.updateOne({ _id: project._id }, { progress: pt.length ? Math.round((done / pt.length) * 100) : 0 });
  }
  const projectTasks = tasks.filter((t) => t.project);
  console.log(`  tasks:          ${tasks.length}`);

  // ── Comments ─────────────────────────────────────────────────────────────
  const comments = [];
  for (const task of faker.helpers.arrayElements(projectTasks, 45)) {
    for (let c = 0; c < faker.number.int({ min: 1, max: 3 }); c++) {
      comments.push({
        content: pick([
          'Pushed the first draft — feedback welcome.', "Client approved this on today's call.",
          'Blocked until we get the final assets.', 'Looks good to me, moving to review.',
          'Can we push the deadline by two days?', 'Added notes to the checklist.',
          faker.lorem.sentence(),
        ]),
        author: pick(staff)._id, task: task._id, project: task.project,
        createdAt: faker.date.recent({ days: 14 }),
      });
    }
  }
  await Comment.insertMany(comments);
  console.log(`  comments:       ${comments.length}`);

  // ── Attendance: last 30 days + today ─────────────────────────────────────
  const attendance = [];
  for (let off = 30; off >= 0; off--) {
    const day = daysFromToday(-off);
    if (isWeekend(day)) continue;
    for (const u of staff) {
      const status = faker.helpers.weightedArrayElement([
        { value: 'present' as const, weight: 70 }, { value: 'remote' as const, weight: 14 }, { value: 'late' as const, weight: 6 },
        { value: 'half_day' as const, weight: 4 }, { value: 'leave' as const, weight: 3 }, { value: 'absent' as const, weight: 3 },
      ]);
      if (status === 'absent' || status === 'leave') {
        if (off === 0) continue;
        attendance.push({ user: u._id, date: day, status, workMode: 'office', hoursWorked: 0 });
        continue;
      }
      const late = status === 'late';
      const checkIn = at(day, late ? 10 : 9, faker.number.int({ min: 0, max: late ? 40 : 29 }));
      if (off === 0) { // today: checked in, not yet out
        attendance.push({ user: u._id, date: day, checkIn, status, isLate: late, workMode: status === 'remote' ? 'remote' : 'office' });
        continue;
      }
      const outHour = status === 'half_day' ? 13 : faker.number.int({ min: 17, max: 19 });
      const checkOut = at(day, outHour, faker.number.int({ min: 0, max: 59 }));
      const lunchStart = at(day, 13, faker.number.int({ min: 0, max: 20 }));
      const lunchDuration = status === 'half_day' ? 0 : faker.number.int({ min: 30, max: 50 });
      const hours = (checkOut.getTime() - checkIn.getTime()) / 3.6e6 - lunchDuration / 60;
      attendance.push({
        user: u._id, date: day, checkIn, checkOut, status, isLate: late,
        workMode: status === 'remote' ? 'remote' : pick(['office', 'office', 'hybrid'] as const),
        lunchStart: lunchDuration ? lunchStart : undefined,
        lunchStop: lunchDuration ? new Date(lunchStart.getTime() + lunchDuration * 60000) : undefined,
        lunchDuration, hoursWorked: Math.max(0, Math.round(hours * 100) / 100),
      });
    }
  }
  await Attendance.insertMany(attendance);
  console.log(`  attendance:     ${attendance.length}`);

  // ── Calendar events ──────────────────────────────────────────────────────
  const events = [];
  for (let i = 0; i < 24; i++) {
    const day = daysFromToday(faker.number.int({ min: -10, max: 30 }));
    const type = pick(['meeting', 'meeting', 'reminder', 'event', 'deadline'] as const);
    const h = faker.number.int({ min: 10, max: 17 });
    const project = faker.datatype.boolean() ? pick(projects) : undefined;
    const owner = pick([admin, manager, member, ...staff]);
    events.push({
      title: type === 'meeting' ? pick(['Client check-in', 'Sprint planning', 'Design review', 'Weekly stand-up', 'Quarterly review'])
        : type === 'deadline' ? `Deliverable due: ${pick(TASK_OBJECTS)}` : pick(['Team lunch', 'Workshop: AI tools', 'Office maintenance', 'Invoice run']),
      description: faker.lorem.sentence(), type, date: day,
      startTime: hhmm(h, 0), endTime: hhmm(h + 1, 0), allDay: type === 'deadline',
      color: pick(['#6366f1', '#10b981', '#f59e0b', '#ec4899']),
      project: project?._id, owner: owner._id, createdBy: owner._id,
      invitees: some(staff.map(oid), 1, 4),
      location: type === 'meeting' ? pick(['Google Meet', 'Conference Room A', 'Zoom']) : undefined,
    });
  }
  await CalendarEvent.insertMany(events);
  console.log(`  calendar:       ${events.length}`);

  // ── Notes ────────────────────────────────────────────────────────────────
  const notes = [];
  for (const u of [admin, manager, member, ...faker.helpers.arrayElements(staff.slice(3), 5)]) {
    for (let i = 0; i < faker.number.int({ min: 2, max: 4 }); i++) {
      notes.push({
        title: pick(['Meeting notes', 'Ideas backlog', 'Client feedback', 'To research', 'Retro takeaways']),
        content: faker.lorem.paragraphs(2),
        owner: u._id, color: pick(['', '#fef3c7', '#dcfce7', '#e0e7ff', '#fce7f3']), isPinned: i === 0,
      });
    }
  }
  await Note.insertMany(notes);
  console.log(`  notes:          ${notes.length}`);

  // ── Resources (company equipment) ────────────────────────────────────────
  const resources = staff.flatMap((u) => [
    { name: pick(['MacBook Pro 14"', 'Dell XPS 15', 'ThinkPad X1 Carbon']), category: 'Laptop' },
    ...(faker.datatype.boolean() ? [{ name: pick(['27" 4K Monitor', 'Wacom Tablet', 'Noise-cancelling Headset']), category: 'Accessory' }] : []),
  ].map((r) => ({
    ...r, description: 'Company-issued equipment', assignedTo: u._id, assignedBy: admin._id,
    serialNumber: `SN-${faker.string.alphanumeric({ length: 8, casing: 'upper' })}`,
    condition: pick(['new', 'good', 'good', 'fair'] as const), assignedAt: faker.date.past({ years: 1 }), isActive: true,
  })));
  await Resource.insertMany(resources);
  console.log(`  resources:      ${resources.length}`);

  // ── Credentials vault — fake values, encrypted exactly like real ones ────
  if (process.env.CREDENTIALS_ENCRYPTION_KEY) {
    const creds = projects.slice(0, 6).flatMap((p, i) => [
      { title: 'Website hosting panel', category: 'hosting' as const, url: 'https://hosting.example.com', dept: 'Development' },
      { title: 'Ads manager account',   category: 'ads' as const,     url: 'https://ads.example.com',     dept: 'Marketing' },
    ].map((c) => ({
      title: c.title, project: p._id, department: deptByName.get(c.dept)!._id, category: c.category,
      username: `demo-user-${i + 1}`, secret: encryptSecret('demo-not-a-real-password'), url: c.url,
      expiryDate: daysFromToday(faker.number.int({ min: 5, max: 300 })), notes: 'Demo credential — not real.',
      visibility: 'department' as const, createdBy: admin._id,
    })));
    await Credential.insertMany(creds);
    console.log(`  credentials:    ${creds.length}`);
  } else {
    console.log('  credentials:    skipped (CREDENTIALS_ENCRYPTION_KEY not set)');
  }

  // ── Notifications for the demo accounts ──────────────────────────────────
  const TITLES = { task_assigned: 'New task assigned', status_change: 'Task status updated', comment_mention: 'You were mentioned', deadline_reminder: 'Deadline approaching' } as const;
  const notifs = [];
  for (const u of [admin, manager, member]) {
    for (const task of faker.helpers.arrayElements(projectTasks, 6)) {
      const type = pick(Object.keys(TITLES) as (keyof typeof TITLES)[]);
      notifs.push({
        recipient: u._id, sender: pick(staff.filter((s) => s !== u))._id, type,
        title: TITLES[type], message: task.title, link: `/tasks?task=${task._id}`,
        isRead: faker.datatype.boolean(), createdAt: faker.date.recent({ days: 5 }),
      });
    }
  }
  await Notification.insertMany(notifs);
  console.log(`  notifications:  ${notifs.length}`);

  // ── Chat (private DB) ────────────────────────────────────────────────────
  const conversations = [];
  for (const dept of departments) {
    const ids = [...(dept.members as Types.ObjectId[]), ...(dept.heads as Types.ObjectId[]), oid(admin)];
    const participants = [...new Set(ids.map(String))].map((id) => new Types.ObjectId(id));
    conversations.push(await Conversation.create({
      type: 'department', name: `${dept.name} Team`, department: dept._id,
      participants, admins: dept.heads, createdBy: admin._id,
    }));
  }
  conversations.push(await Conversation.create({
    type: 'group', name: 'General', description: 'Company-wide announcements & banter',
    participants: staff.map(oid), admins: [admin._id], createdBy: admin._id,
  }));
  for (const other of [manager, ...staff.slice(4, 7)]) {
    conversations.push(await Conversation.create({ type: 'direct', participants: [member._id, other._id], createdBy: member._id }));
  }
  const LINES = [
    'Morning all! 👋', 'Has anyone seen the latest client feedback?', 'Uploading the revised mockups now.',
    'Can we sync for 10 mins after lunch?', 'Deployed to staging 🚀', 'Great work on the launch, team!',
    'Reminder: timesheets due Friday.', "I'll pick this up today.", 'The report is in the shared drive.',
    'Sounds good 👍', 'Let me check and get back to you.', 'Client wants a quick call tomorrow at 11.',
  ];
  let messageCount = 0;
  for (const conv of conversations) {
    const people = conv.participants as Types.ObjectId[];
    let time = faker.date.recent({ days: 6 });
    let last;
    for (let m = 0; m < faker.number.int({ min: 6, max: 14 }); m++) {
      time = new Date(time.getTime() + faker.number.int({ min: 2, max: 180 }) * 60000);
      if (time > new Date()) break;
      last = await Message.create({
        conversation: conv._id, sender: pick(people), type: 'text', content: pick(LINES),
        seenBy: some(people, 1, people.length).map((u) => ({ user: u, seenAt: time })),
        reactions: faker.number.int({ max: 5 }) === 0 ? [{ emoji: pick(['👍', '🎉', '❤️']), users: some(people, 1, 3) }] : [],
        createdAt: time, updatedAt: time,
      });
      messageCount++;
    }
    if (last) await Conversation.updateOne({ _id: conv._id }, { lastMessage: last._id, lastActivity: time });
  }
  console.log(`  conversations:  ${conversations.length}  (messages: ${messageCount})`);

  console.log(`\nWorkspace demo data ready. Demo logins (password for all: ${DEMO_PASSWORD}):`);
  for (const a of demoAccounts) console.log(`  ${a.role.padEnd(8)} ${a.email}`);
}

if (require.main === module) {
  seedWorkspace()
    .then(async () => { await mongoose.disconnect(); await privateConn.close(); process.exit(0); })
    .catch((err) => { console.error('Seed failed:', err); process.exit(1); });
}
